        if(nums == null || nums.length == 0) return 0;
        if(numOperations < 0) return 0;
        if(nums.length == 1) return 1;

        int res = 0;
        TreeMap<Integer, Integer> freq = new TreeMap<>(); // nums[i] -> freq
        HashMap<Integer, Integer> valToId = new HashMap<>();
        HashMap<Integer, Integer> idToVal = new HashMap<>();

        for(int i=0; i<nums.length; i++){
            freq.put(nums[i], freq.getOrDefault(nums[i], 0) + 1);
            freq.putIfAbsent(nums[i] + k, 0);
            freq.putIfAbsent(nums[i] - k, 0);
        }

        int[] prefixSum = new int[freq.size()];
        int idx = 0;
        for(int key: freq.keySet()){
            valToId.put(key, idx);
            idToVal.put(idx, key);
            prefixSum[idx] = freq.get(key) + (idx == 0 ? 0: prefixSum[idx-1]);
            idx++;
        }

        for(int i=0; i<prefixSum.length; i++){
            Integer floor = freq.floorKey(idToVal.get(i) + k);
            Integer ceil = freq.ceilingKey(idToVal.get(i) - k);

            int idx2 = valToId.get(floor);
            int idx1 = valToId.get(ceil);

            int sum = prefixSum[idx2] - (idx1 == 0 ? 0: prefixSum[idx1-1]);
            int currOp = Math.min(numOperations, sum - freq.get(idToVal.get(i)));

            res = Math.max(res, freq.get(idToVal.get(i)) + currOp);
        }
        return res;
    }'
